"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3246],{9124:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SeasonService","desc":"Server-authoritative Season Pass (battle pass) logic:\\n\\n- `addSeasonXP` accrues season currency (call it from your game\'s own\\n  progression choke points, or let challenges be the only source).\\n- `reportChallenge` advances weekly-challenge progress from your game\'s\\n  progress signals, granting the challenge\'s `xpReward` once on completion.\\n  Wire your game systems to call this with the metrics authored in\\n  SeasonData (placeholders until you rename them).\\n- `claim` validates a tier/track claim server-side and pays out coins.\\n- The premium DevProduct receipt flips `season.premium` for the CURRENT\\n  season (registered via MarketplaceData in `init`).","source":{"line":19,"path":"src/Server/Features/Season/SeasonService.luau"}}')}}]);